import numpy as np

def generate_entries(features, signal_params):
    n = features.market.size
    opens = np.asarray(features.market.opens, dtype=np.float64)
    highs = np.asarray(features.market.highs, dtype=np.float64)
    lows = np.asarray(features.market.lows, dtype=np.float64)
    closes = np.asarray(features.market.closes, dtype=np.float64)
    volumes = np.asarray(features.market.volumes, dtype=np.float64)
    volume_sma_length = int(signal_params['volume_sma_length'])
    volume_ratio_min = float(signal_params['volume_ratio_min'])
    body_pct_max = float(signal_params['body_pct_max'])
    upper_wick_pct_min = float(signal_params['upper_wick_pct_min'])
    upper_to_lower_wick_multiplier = float(signal_params['upper_to_lower_wick_multiplier'])
    volume_sma = features.sma(volume_sma_length, 'volumes')
    candle_range = highs - lows
    body = np.abs(closes - opens)
    lower_wick = np.minimum(opens, closes) - lows
    upper_wick = highs - np.maximum(opens, closes)
    body_pct = np.divide(body * 100.0, candle_range, out=np.zeros(n, dtype=np.float64), where=candle_range > 0)
    upper_wick_pct = np.divide(upper_wick * 100.0, candle_range, out=np.zeros(n, dtype=np.float64), where=candle_range > 0)
    volume_ratio = np.divide(volumes, volume_sma, out=np.zeros(n, dtype=np.float64), where=volume_sma > 0)
    long_entries = np.zeros(n, dtype=bool)
    short_entries = ((candle_range > 0) & (volume_sma > 0) & (volume_ratio >= volume_ratio_min) & (body_pct <= body_pct_max) & (upper_wick_pct >= upper_wick_pct_min) & (upper_wick >= lower_wick * upper_to_lower_wick_multiplier) & (closes <= (highs + lows) / 2.0)).astype(bool)
    return (long_entries, short_entries)

def i5_apply_trend_exit(features: object, long_entries: object, short_entries: object, signal_params: dict) -> tuple:
    return features.trend_exit(long_entries, short_entries)

def generate_signals(features, signal_params):
    long_entries, short_entries = generate_entries(features, signal_params)
    long_exits, short_exits = i5_apply_trend_exit(features, long_entries, short_entries, signal_params)
    no_distances = np.full(features.market.size, np.nan, dtype=np.float64)
    return (long_entries, long_exits, short_entries, short_exits, no_distances, no_distances)

